"use client";

import React, { useEffect, useState } from "react";
import axios from "axios";
import { useRouter } from "next/navigation";
import Link from "next/link";

import { Sidebar } from "@/components/sidebar";
import { TopBar } from "@/components/topbar";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";

interface Video {
  id: string;
  title: string;
  video_url: string;
  status: "processing" | "summarized" | "failed";
}

export default function HistoryPage() {
  const router = useRouter();
  const [videos, setVideos] = useState<Video[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const token = localStorage.getItem("token");

    // 🔐 Protect history page
    if (!token) {
      router.push("/login");
      return;
    }

    fetchHistory(token);
  }, []);

  const fetchHistory = async (token: string) => {
    try {
      const response = await axios.get(
        "http://127.0.0.1:5000/api/video/my-videos",
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      setVideos(response.data);
    } catch (error) {
      console.error("Error fetching history", error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex h-screen bg-background">
      <Sidebar />

      <div className="flex-1 flex flex-col overflow-hidden">
        <TopBar />

        <main className="flex-1 overflow-auto">
          <div className="p-8 max-w-6xl mx-auto space-y-6">

            <h1 className="text-2xl font-semibold text-foreground">
              History
            </h1>

            {loading ? (
              <p className="text-muted-foreground">Loading history...</p>
            ) : videos.length === 0 ? (
              <p className="text-muted-foreground">
                No videos found.
              </p>
            ) : (
              <div className="space-y-4">
                {videos.map((video) => (
                  <Link key={video.id} href={`/lecture/${video.id}`}>
                    <Card className="p-4 border-border/50 hover:bg-muted/50 transition cursor-pointer">
                      <div className="flex items-center justify-between">
                        <div>
                          <h3 className="font-semibold text-foreground">
                            {video.title || "Untitled Lecture"}
                          </h3>
                          <p className="text-sm text-muted-foreground">
                            {video.video_url}
                          </p>
                        </div>

                        <div className="flex items-center gap-3">
                          <span
                            className={`px-3 py-1 rounded-full text-xs font-medium ${
                              video.status === "summarized"
                                ? "bg-green-500/10 text-green-700"
                                : video.status === "failed"
                                ? "bg-red-500/10 text-red-700"
                                : "bg-yellow-500/10 text-yellow-700"
                            }`}
                          >
                            {video.status}
                          </span>

                          {video.status === "summarized" && (
                            <div className="flex gap-2">
                              <Link href={`/summary/${video.id}`}>
                                <Button size="sm" variant="outline">
                                  Summary
                                </Button>
                              </Link>
                              <Link href={`/concept-map/${video.id}`}>
                                <Button size="sm" className="bg-accent">
                                  Map
                                </Button>
                              </Link>
                            </div>
                          )}
                        </div>
                      </div>
                    </Card>
                  </Link>
                ))}
              </div>
            )}

          </div>
        </main>
      </div>
    </div>
  );
}